package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_visit_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock private NodeTraversal mockTraversal;
    @Mock private Node mockNode;
    @Mock private Node mockParent;
    @Mock private Compiler mockCompiler;
    @Mock private CompilerError mockError;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        checkGlobalThis = new CheckGlobalThis();
        // Using reflection or assuming internal access if possible to set compiler
        // Since we cannot change the source, we assume the compiler is injected or accessible
        // For the sake of this test, we assume the field 'compiler' is accessible or set via a mechanism
        setCompiler(checkGlobalThis, mockCompiler);
    }

    // Helper to inject the mock compiler into the private field
    private void setCompiler(CheckGlobalThis instance, Compiler compiler) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("compiler");
            field.setAccessible(true);
            field.set(instance, compiler);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testVisit_NotThis_DoesNotReport() {
        when(mockNode.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(mockTraversal, mockNode, mockParent);

        verify(mockCompiler, never()).report(any());
    }

    @Test
    public void testVisit_IsThis_ShouldNotReport() {
        when(mockNode.getType()).thenReturn(Token.THIS);
        // We need to mock shouldReportThis. Since it is likely a private/protected method 
        // in the same class, we rely on the logic of the implementation.
        // If shouldReportThis is a method in the same class, we can't easily mock it without Spy.
        // Let's use a Spy to control shouldReportThis.

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        org.mockito.Mockito.doReturn(false).when(spyCheck).shouldReportThis(mockNode, mockParent);

        spyCheck.visit(mockTraversal, mockNode, mockParent);

        verify(mockCompiler, never()).report(any());
    }

    @Test
    public void testVisit_IsThis_ShouldReport() {
        when(mockNode.getType()).thenReturn(Token.THIS);
        when(mockTraversal.makeError(any(), any(), any())).thenReturn(mockError);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(mockNode, mockParent);

        spyCheck.visit(mockTraversal, mockNode, mockParent);

        verify(mockCompiler).report(mockError);
    }

    @Test
    public void testVisit_AssignLhsChildMatch() throws Exception {
        // We need to set assignLhsChild to the mockNode to test the nulling logic
        java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        field.setAccessible(true);
        field.set(checkGlobalThis, mockNode);

        when(mockNode.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(mockTraversal, mockNode, mockParent);

        // Verify field is now null
        assert(field.get(checkGlobalThis) == null);
    }

    @Test
    public void testVisit_AssignLhsChildNotMatch() throws Exception {
        Node otherNode = mock(Node.class);
        when(otherNode.getType()).thenReturn(Token.NAME);

        java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        field.setAccessible(true);
        field.set(checkGlobalThis, mockNode); // assignLhsChild is mockNode

        checkGlobalThis.visit(mockTraversal, otherNode, mockParent);

        // Verify field is still mockNode
        assert(field.get(checkGlobalThis) == mockNode);
    }
}
